  async fetchAddressDetailsByPincode(pin) {
    if (!pin || String(pin).length !== 6) return null;
    const cleanPin = String(pin).trim();
    const spinner = document.getElementById('new-jc-pin-spinner');
    const feedback = document.getElementById('new-jc-pin-feedback');

    if (spinner) spinner.style.display = 'inline-block';
    if (feedback) {
      feedback.style.display = 'block';
      feedback.style.color = 'var(--text-muted, #94a3b8)';
      feedback.innerHTML = '🔍 Fetching City, District & State...';
    }

    // 1. Local catalog & DB
    let details = this.lookupPincodeLocal(cleanPin);

    // 2. India Post Public API fallback
    if (!details && typeof fetch === 'function') {
      try {
        const resp = await fetch(`https://api.postalpincode.in/pincode/${cleanPin}`);
        if (resp.ok) {
          const data = await resp.json();
          if (Array.isArray(data) && data[0] && data[0].Status === 'Success' && Array.isArray(data[0].PostOffice) && data[0].PostOffice.length > 0) {
            const po = data[0].PostOffice[0];
            const city = (po.Block && po.Block !== 'NA') ? po.Block : (po.District || po.Name);
            const district = po.District || city;
            const state = po.State || 'Maharashtra';
            details = { city, district, state, area: po.Name, source: 'INDIA_POST_API' };
            this._pincodeCache = this._pincodeCache || {};
            this._pincodeCache[cleanPin] = details;
          }
        }
      } catch (err) {}
    }

    // 3. Postal Circle Heuristic fallback
    if (!details) {
      details = this.getHeuristicPincodeDetails(cleanPin);
    }

    if (spinner) spinner.style.display = 'none';

    if (details) {
      this.applyAddressDetailsToModal(details);
    } else {
      if (feedback) {
        feedback.style.display = 'block';
        feedback.style.color = 'var(--text-muted, #94a3b8)';
        feedback.innerHTML = 'ℹ️ PIN code entered. Enter City & State manually.';
      }
    }
    return details;
  },

  applyAddressDetailsToModal(details) {
    if (!details) return;
    const cityInput = document.getElementById('new-jc-city');
    const distInput = document.getElementById('new-jc-district');
    const stateInput = document.getElementById('new-jc-state');
    const feedback = document.getElementById('new-jc-pin-feedback');

    if (cityInput && details.city) cityInput.value = details.city;
    if (distInput && details.district) distInput.value = details.district;
    if (stateInput && details.state) stateInput.value = details.state;

    // Green glow highlight feedback
    [cityInput, distInput, stateInput].forEach(el => {
      if (el) {
        el.style.transition = 'all 0.3s ease';
        el.style.borderColor = 'var(--color-success, #10b981)';
        el.style.boxShadow = '0 0 0 2px rgba(16, 185, 129, 0.25)';
        setTimeout(() => {
          el.style.borderColor = '';
          el.style.boxShadow = '';
        }, 1800);
      }
    });

    if (feedback) {
      feedback.style.display = 'block';
      feedback.style.color = 'var(--color-success, #10b981)';
      const parts = [details.city, details.district, details.state].filter(Boolean);
      feedback.innerHTML = `✓ Auto-fetched: <b>${parts.join(', ')}</b>`;
    }
  },

  onPincodeInput(input) {
    if (!input) return;
    input.value = input.value.replace(/\D/g, '').slice(0, 6);
    const feedback = document.getElementById('new-jc-pin-feedback');
    if (input.value.length === 6) {
      this.fetchAddressDetailsByPincode(input.value);
    } else {
      if (feedback) {
        feedback.style.display = 'none';
        feedback.innerHTML = '';
      }
    }
  },

  onPincodeBlur(input) {
    if (!input) return;
    if (input.value.length === 6) {
      this.fetchAddressDetailsByPincode(input.value);
    }
  },

  onPincodePaste(event, input) {
    setTimeout(() => {
      if (input) {
        input.value = input.value.replace(/\D/g, '').slice(0, 6);
        if (input.value.length === 6) {
          this.fetchAddressDetailsByPincode(input.value);
        }
      }
    }, 0);
  },

