                <input type="text" id="new-jc-color" class="form-control form-control-sm" placeholder="e.g. Matte Black" style="height: 22px; font-size: 10.5px; padding: 1px 6px;" ${isMan('VEHICLE', 'color') ? 'required' : ''} />
