    const remarks = remarksEl ? remarksEl.value.trim() : '';
    if (!reason) {
      window.State.showToast('Cancellation reason is mandatory.', 'danger');
      return;
    }

    const receipts = this.getBillReceipts(bill.id);
    const activeReceipts = receipts.filter(r => r.status !== 'CANCELLED');
    const user = (window.State && window.State.getCurrentUser && window.State.getCurrentUser()) || (window.State && window.State.currentUser) || {};
